package jlsm.engine.internal;

import jlsm.engine.TableMetadata;
import jlsm.table.JlsmSchema;

import java.io.Closeable;
import java.io.IOException;
import java.nio.file.Path;
import java.util.Collection;
import java.util.Objects;
import java.util.Optional;

/**
 * Manages per-table directory layout, metadata persistence, and lazy table loading.
 *
 * <p>
 * Each table lives in its own subdirectory under the engine root. The catalog scans
 * the root directory on {@link #open()} to discover existing tables and builds lightweight
 * metadata handles. Full table initialization is deferred until first access.
 *
 * <p>
 * Governed by: {@code .decisions/table-catalog-persistence/adr.md}
 */
final class TableCatalog implements Closeable {

    private final Path rootDir;

    /**
     * Constructs a new TableCatalog for the given root directory.
     *
     * @param rootDir the engine root directory; must not be null
     */
    TableCatalog(Path rootDir) {
        this.rootDir = Objects.requireNonNull(rootDir, "rootDir must not be null");
    }

    /**
     * Opens the catalog by scanning the root directory for existing table subdirectories.
     * Builds lightweight metadata handles without fully initializing tables.
     *
     * @throws IOException if the root directory cannot be read or is corrupt
     */
    void open() throws IOException {
        throw new UnsupportedOperationException("Not implemented");
    }

    /**
     * Registers a new table by creating its subdirectory and metadata file.
     *
     * @param name   the table name; must not be null or empty
     * @param schema the table schema; must not be null
     * @return the metadata for the newly registered table
     * @throws IOException if the table already exists or the directory cannot be created
     */
    TableMetadata register(String name, JlsmSchema schema) throws IOException {
        Objects.requireNonNull(name, "name must not be null");
        Objects.requireNonNull(schema, "schema must not be null");
        if (name.isEmpty()) {
            throw new IllegalArgumentException("name must not be empty");
        }
        throw new UnsupportedOperationException("Not implemented");
    }

    /**
     * Unregisters a table by removing its subdirectory and all contained files.
     *
     * @param name the table name; must not be null or empty
     * @throws IOException if the table does not exist or cannot be removed
     */
    void unregister(String name) throws IOException {
        Objects.requireNonNull(name, "name must not be null");
        if (name.isEmpty()) {
            throw new IllegalArgumentException("name must not be empty");
        }
        throw new UnsupportedOperationException("Not implemented");
    }

    /**
     * Returns metadata for a specific table, or empty if not registered.
     *
     * @param name the table name; must not be null
     * @return an Optional containing the metadata, or empty if not found
     */
    Optional<TableMetadata> get(String name) {
        Objects.requireNonNull(name, "name must not be null");
        throw new UnsupportedOperationException("Not implemented");
    }

    /**
     * Returns metadata for all known tables.
     *
     * @return an unmodifiable collection of table metadata; never null
     */
    Collection<TableMetadata> list() {
        throw new UnsupportedOperationException("Not implemented");
    }

    /**
     * Returns the directory path for a given table.
     *
     * @param name the table name; must not be null
     * @return the table's subdirectory path; never null
     */
    Path tableDirectory(String name) {
        Objects.requireNonNull(name, "name must not be null");
        throw new UnsupportedOperationException("Not implemented");
    }

    /**
     * Returns true if the catalog is still loading (scanning the root directory).
     *
     * @return true if loading is in progress
     */
    boolean isLoading() {
        throw new UnsupportedOperationException("Not implemented");
    }

    @Override
    public void close() throws IOException {
        throw new UnsupportedOperationException("Not implemented");
    }
}

package jlsm.engine;

import jlsm.table.JlsmSchema;

import java.io.Closeable;
import java.io.IOException;
import java.util.Collection;

/**
 * Engine lifecycle and table management interface.
 *
 * <p>
 * Manages the lifecycle of multiple named tables within a single root directory. Each table is
 * backed by its own subdirectory containing WAL, SSTable, and metadata files. The engine handles
 * catalog persistence, lazy table initialization, and handle tracking.
 *
 * <p>
 * Governed by: {@code .decisions/engine-api-surface-design/adr.md}
 */
public interface Engine extends Closeable {

    /**
     * Creates a new table with the given name and schema.
     *
     * @param name   the table name; must not be null or empty
     * @param schema the table schema; must not be null
     * @return a handle to the newly created table
     * @throws IllegalArgumentException if name is null or empty, or schema is null
     * @throws IOException              if a table with the given name already exists, or on I/O failure
     */
    Table createTable(String name, JlsmSchema schema) throws IOException;

    /**
     * Returns a handle to an existing table.
     *
     * @param name the table name; must not be null or empty
     * @return a handle to the table
     * @throws IllegalArgumentException if name is null or empty
     * @throws IOException              if no table with the given name exists, or on I/O failure
     */
    Table getTable(String name) throws IOException;

    /**
     * Drops an existing table, removing its catalog entry and storage.
     *
     * @param name the table name; must not be null or empty
     * @throws IllegalArgumentException if name is null or empty
     * @throws IOException              if no table with the given name exists, or on I/O failure
     */
    void dropTable(String name) throws IOException;

    /**
     * Returns metadata for all known tables.
     *
     * @return an unmodifiable collection of table metadata; never null
     */
    Collection<TableMetadata> listTables();

    /**
     * Returns metadata for a specific table, or null if not found.
     *
     * @param name the table name; must not be null or empty
     * @return the table metadata, or null if no table with the given name exists
     */
    TableMetadata tableMetadata(String name);

    /**
     * Returns a snapshot of engine-wide metrics.
     *
     * @return the current engine metrics; never null
     */
    EngineMetrics metrics();

    /**
     * Closes the engine, force-invalidating all outstanding table handles and flushing
     * all tables.
     *
     * @throws IOException if an I/O error occurs during shutdown
     */
    @Override
    void close() throws IOException;
}

package jlsm.engine;

import jlsm.table.DuplicateKeyException;
import jlsm.table.JlsmDocument;
import jlsm.table.KeyNotFoundException;
import jlsm.table.TableEntry;
import jlsm.table.TableQuery;
import jlsm.table.UpdateMode;

import java.io.IOException;
import java.util.Iterator;
import java.util.Optional;

/**
 * A tracked table handle providing data operations and query pass-through.
 *
 * <p>
 * Each call to {@link Engine#getTable(String)} or {@link Engine#createTable} returns a new tracked
 * handle. The handle must be closed when no longer needed. Operations on a closed or evicted
 * handle throw {@link HandleEvictedException}.
 *
 * <p>
 * Governed by: {@code .decisions/engine-api-surface-design/adr.md}
 */
public interface Table extends AutoCloseable {

    /**
     * Creates a new entry with the given key and document.
     *
     * @param key the entry key; must not be null
     * @param doc the document to store; must not be null
     * @throws DuplicateKeyException   if an entry with the given key already exists
     * @throws HandleEvictedException  if this handle has been evicted or closed
     * @throws IOException             on I/O failure
     */
    void create(String key, JlsmDocument doc) throws IOException;

    /**
     * Returns the document associated with the given key, or empty if not found.
     *
     * @param key the entry key; must not be null
     * @return an Optional containing the document, or empty if absent
     * @throws HandleEvictedException if this handle has been evicted or closed
     * @throws IOException            on I/O failure
     */
    Optional<JlsmDocument> get(String key) throws IOException;

    /**
     * Updates an existing entry.
     *
     * @param key  the entry key; must not be null
     * @param doc  the new document; must not be null
     * @param mode the update mode (REPLACE or PATCH)
     * @throws KeyNotFoundException   if no entry with the given key exists
     * @throws HandleEvictedException if this handle has been evicted or closed
     * @throws IOException            on I/O failure
     */
    void update(String key, JlsmDocument doc, UpdateMode mode) throws IOException;

    /**
     * Deletes the entry with the given key.
     *
     * @param key the entry key; must not be null
     * @throws HandleEvictedException if this handle has been evicted or closed
     * @throws IOException            on I/O failure
     */
    void delete(String key) throws IOException;

    /**
     * Inserts a document using its schema-defined primary key.
     *
     * @param doc the document to insert; must not be null
     * @throws HandleEvictedException if this handle has been evicted or closed
     * @throws IOException            on I/O failure
     */
    void insert(JlsmDocument doc) throws IOException;

    /**
     * Returns a fluent query builder bound to this table.
     *
     * @return a new query builder; never null
     * @throws HandleEvictedException if this handle has been evicted or closed
     */
    TableQuery<String> query();

    /**
