package jlsm.engine.internal;

import jlsm.engine.HandleEvictedException;
import jlsm.engine.Table;
import jlsm.engine.TableMetadata;
import jlsm.table.DuplicateKeyException;
import jlsm.table.JlsmDocument;
import jlsm.table.JlsmTable;
import jlsm.table.KeyNotFoundException;
import jlsm.table.TableEntry;
import jlsm.table.TableQuery;
import jlsm.table.UpdateMode;

import java.io.IOException;
import java.util.Iterator;
import java.util.Objects;
import java.util.Optional;

/**
 * Local implementation of {@link Table} wrapping a {@link JlsmTable.StringKeyed} with
 * handle lifecycle tracking.
 *
 * <p>
 * Every method checks handle validity before delegating to the underlying table.
 * If the handle has been evicted, a {@link HandleEvictedException} is thrown.
 *
 * <p>
 * Governed by: {@code .decisions/engine-api-surface-design/adr.md}
 */
final class LocalTable implements Table {

    private final JlsmTable.StringKeyed delegate;
    private final HandleRegistration registration;
    private final HandleTracker tracker;
    private final TableMetadata metadata;

    LocalTable(JlsmTable.StringKeyed delegate, HandleRegistration registration,
               HandleTracker tracker, TableMetadata metadata) {
        this.delegate = Objects.requireNonNull(delegate, "delegate must not be null");
        this.registration = Objects.requireNonNull(registration, "registration must not be null");
        this.tracker = Objects.requireNonNull(tracker, "tracker must not be null");
        this.metadata = Objects.requireNonNull(metadata, "metadata must not be null");
    }

    @Override
    public void create(String key, JlsmDocument doc) throws IOException {
        Objects.requireNonNull(key, "key must not be null");
        Objects.requireNonNull(doc, "doc must not be null");
        checkValid();
        throw new UnsupportedOperationException("Not implemented");
    }

    @Override
    public Optional<JlsmDocument> get(String key) throws IOException {
        Objects.requireNonNull(key, "key must not be null");
        checkValid();
        throw new UnsupportedOperationException("Not implemented");
    }

    @Override
    public void update(String key, JlsmDocument doc, UpdateMode mode) throws IOException {
        Objects.requireNonNull(key, "key must not be null");
        Objects.requireNonNull(doc, "doc must not be null");
        Objects.requireNonNull(mode, "mode must not be null");
        checkValid();
        throw new UnsupportedOperationException("Not implemented");
    }

    @Override
    public void delete(String key) throws IOException {
        Objects.requireNonNull(key, "key must not be null");
        checkValid();
        throw new UnsupportedOperationException("Not implemented");
    }

    @Override
    public void insert(JlsmDocument doc) throws IOException {
        Objects.requireNonNull(doc, "doc must not be null");
        checkValid();
        throw new UnsupportedOperationException("Not implemented");
    }

    @Override
    public TableQuery<String> query() {
        checkValid();
        throw new UnsupportedOperationException("Not implemented");
    }

    @Override
    public Iterator<TableEntry<String>> scan(String fromKey, String toKey) throws IOException {
        Objects.requireNonNull(fromKey, "fromKey must not be null");
        Objects.requireNonNull(toKey, "toKey must not be null");
        checkValid();
        throw new UnsupportedOperationException("Not implemented");
    }

    @Override
    public TableMetadata metadata() {
        return metadata;
    }

    @Override
    public void close() {
        tracker.release(registration);
    }

    /**
     * Checks that this handle has not been evicted or invalidated.
     *
     * @throws HandleEvictedException if the handle is invalid
     */
    private void checkValid() {
        if (registration.isInvalidated()) {
            throw new HandleEvictedException(
                    registration.tableName(),
                    registration.sourceId(),
                    0,
                    registration.allocationSite(),
                    HandleEvictedException.Reason.EVICTION);
        }
    }
}

package jlsm.table;

import java.io.Closeable;
import java.io.IOException;
import java.util.Iterator;
import java.util.Optional;

/**
 * A typed document table backed by an LSM-Tree.
 *
 * <p>
 * Two key types are provided via the nested sealed sub-interfaces: {@link StringKeyed} for string
 * keys and {@link LongKeyed} for long keys.
 */
public sealed interface JlsmTable extends Closeable
        permits JlsmTable.StringKeyed, JlsmTable.LongKeyed {

    /** A {@link JlsmTable} keyed by {@link String}. */
    non-sealed interface StringKeyed extends JlsmTable {

        /**
         * Creates a new entry. Throws {@link DuplicateKeyException} if the key exists.
         *
         * @param key the key; must not be null
         * @param doc the document to store; must not be null
         * @throws DuplicateKeyException if an entry with the given key already exists
         * @throws IOException on I/O failure
         */
        void create(String key, JlsmDocument doc) throws IOException;

        /**
         * Returns the document associated with the given key, or empty if not found.
         *
         * @param key the key; must not be null
         * @return an Optional containing the document, or empty if absent
         * @throws IOException on I/O failure
         */
        Optional<JlsmDocument> get(String key) throws IOException;

        /**
         * Updates an existing entry. Throws {@link KeyNotFoundException} if not found.
         *
         * @param key the key; must not be null
         * @param doc the new document; must not be null
         * @param mode the update mode (REPLACE or PATCH)
         * @throws KeyNotFoundException if no entry with the given key exists
         * @throws IOException on I/O failure
         */
        void update(String key, JlsmDocument doc, UpdateMode mode) throws IOException;

        /**
         * Deletes the entry with the given key.
         *
         * @param key the key; must not be null
         * @throws IOException on I/O failure
         */
        void delete(String key) throws IOException;

        /**
         * Returns an iterator over all entries with keys in the range [{@code from}, {@code to}).
         *
         * @param from the inclusive lower bound; must not be null
         * @param to the exclusive upper bound; must not be null
         * @return an iterator of {@link TableEntry} values
         * @throws IOException on I/O failure
         */
        Iterator<TableEntry<String>> getAllInRange(String from, String to) throws IOException;

        /** Builder for {@link StringKeyed} tables. */
        interface Builder {
            JlsmTable.StringKeyed build();
        }
    }

    /** A {@link JlsmTable} keyed by {@code long}. */
    non-sealed interface LongKeyed extends JlsmTable {

        /**
         * Creates a new entry. Throws {@link DuplicateKeyException} if the key exists.
         *
         * @param key the key
         * @param doc the document to store; must not be null
         * @throws DuplicateKeyException if an entry with the given key already exists
         * @throws IOException on I/O failure
         */
        void create(long key, JlsmDocument doc) throws IOException;

        /**
         * Returns the document associated with the given key, or empty if not found.
         *
         * @param key the key
         * @return an Optional containing the document, or empty if absent
         * @throws IOException on I/O failure
         */
        Optional<JlsmDocument> get(long key) throws IOException;

        /**
         * Updates an existing entry. Throws {@link KeyNotFoundException} if not found.
         *
         * @param key the key
         * @param doc the new document; must not be null
         * @param mode the update mode (REPLACE or PATCH)
         * @throws KeyNotFoundException if no entry with the given key exists
         * @throws IOException on I/O failure
         */
        void update(long key, JlsmDocument doc, UpdateMode mode) throws IOException;

        /**
         * Deletes the entry with the given key.
         *
         * @param key the key
         * @throws IOException on I/O failure
         */
        void delete(long key) throws IOException;

        /**
         * Returns an iterator over all entries with keys in the range [{@code from}, {@code to}).
         *
         * @param from the inclusive lower bound
         * @param to the exclusive upper bound
         * @return an iterator of {@link TableEntry} values
         * @throws IOException on I/O failure
         */
        Iterator<TableEntry<Long>> getAllInRange(long from, long to) throws IOException;

        /** Builder for {@link LongKeyed} tables. */
        interface Builder {
            JlsmTable.LongKeyed build();
        }
    }
}

